sys_script_include.script:
var LabTestUtils = Class.create();
LabTestUtils.prototype = {
    initialize: function () {
    },

    /* 1️⃣  Fetch lab‑test results by Test Number */
    getLabTestResultsById: function (testNumber) {
        var gr = new GlideRecord('u_lab_test');
        gr.addQuery('number', testNumber);        // LAB0001008, etc.
        gr.query();
        if (gr.next()) {
            // return "TestType;Results"
            return gr.getValue('u_test_type') + ';' + gr.getValue('u_results');
        }
        return false;
    },

    /* 2️⃣  Check if results are ready (Status = Completed & results not empty) */
    isLabTestResultReady: function (testNumber) {
        var gr = new GlideRecord('u_lab_test');
        gr.addQuery('number', testNumber);
        gr.addQuery('u_status', 'Completed');
        gr.addNotNullQuery('u_results');
        gr.query();
        return gr.hasNext();   // true / false
    },

    /* 3️⃣  Get all lab tests for a patient */
    getLabTestsByPatient: function (patientId) {
        var result = '';
        var gr = new GlideRecord('u_lab_test');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.query();
        while (gr.next()) {
            // "Number;TestType;Status"
            result += gr.getValue('number') + ';' + gr.getValue('u_test_type') + ';' +
                      gr.getValue('u_status') + '\n';
        }
        return result || false;
    },

    /* 4️⃣  Get lab tests by scheduled date (YYYY‑MM‑DD) */
    getLabTestsByDate: function (dateStr) {
        var result = '';
        var gr = new GlideRecord('u_lab_test');
        gr.addQuery('u_scheduled_date', 'STARTSWITH', dateStr);  // e.g. "2025-06-20"
        gr.query();
        while (gr.next()) {
            // "Number;PatientID;TestType"
            result += gr.getValue('number') + ';' +
                      gr.getDisplayValue('u_patient_id') + ';' +
                      gr.getValue('u_test_type') + '\n';
        }
        return result || false;
    },

    type: 'LabTestUtils'
};
